export const uploadFile = async (
  args: { name: string; size: number; mimeType: string; folderId: number | null; content: string },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Not authorized");
  }
  if (!args.name || !args.content) {
    throw new HttpError(400, "File name and content are required");
  }

  const uploadsDir = "/home/user/app/uploads";
  fs.mkdirSync(uploadsDir, { recursive: true });

  const fileUUID = crypto.randomUUID();
  const uniqueFileName = `${fileUUID}-${args.name}`;
  const filePath = path.join(uploadsDir, uniqueFileName);

  // Decode base64 and write
  fs.writeFileSync(filePath, Buffer.from(args.content, "base64"));

  return context.entities.File.create({
    data: {
      name: args.name,
      size: args.size,
      mimeType: args.mimeType,
      filePath: filePath,
      folderId: args.folderId,
      userId: context.user.id,
    },
  });
};

export const createShareLink = async (
  args: { fileId: number; password?: string; expiresInMinutes?: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Not authorized");
  }

  // Verify file ownership
  const file = await context.entities.File.findUnique({
    where: { id: args.fileId, userId: context.user.id },
  });
  if (!file) {
    throw new HttpError(404, "File not found");
  }

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  return context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password: args.password || null,
      expiresAt: expiresAt,
    },
  });
};

import fs from "fs";
import { Request, Response } from "express";

export const downloadFile = async (req: Request, res: Response, context: any) => {
  const { linkId } = req.params;
  const password = req.query.password as string | undefined;

  try {
    // 1. Fetch the share link
    const shareLink = await context.entities.ShareLink.findUnique({
      where: { id: linkId },
      include: { file: true },
    });

    if (!shareLink) {
      return res.status(404).json({ error: "Share link not found" });
    }

    // 2. Check expiration
    if (shareLink.expiresAt && new Date() > new Date(shareLink.expiresAt)) {
      return res.status(410).json({ error: "Link has expired" });
    }

    // 3. Check password
    if (shareLink.password && shareLink.password !== password) {
      return res.status(403).json({ error: "Invalid password" });
    }

    const file = shareLink.file;
    if (!file) {
      return res.status(404).json({ error: "File not found" });
    }

    // 4. Verify file exists on disk
    if (!fs.existsSync(file.filePath)) {
      return res.status(404).json({ error: "File physical content not found" });
    }

    // 5. Log the access
    // Extract IP address and User-Agent
    const ipAddress = (req.headers["x-forwarded-for"] as string) || req.socket.remoteAddress || "unknown";
    const userAgent = req.headers["user-agent"] || "unknown";

    await context.entities.AccessLog.create({
      data: {
        fileId: file.id,
        shareLinkId: shareLink.id,
        ipAddress: ipAddress,
        userAgent: userAgent,
      },
    });

    // 6. Serve the file
    res.setHeader("Content-Disposition", `attachment; filename="${encodeURIComponent(file.name)}"`);
    res.setHeader("Content-Type", file.mimeType);
    res.setHeader("Content-Length", file.size);

    const fileStream = fs.createReadStream(file.filePath);
    fileStream.pipe(res);

  } catch (error: any) {
    console.error("Download error:", error);
    return res.status(500).json({ error: "Internal server error" });
  }
};

